package de.fitnesscoach.data.repository;
import java.time.LocalDate;import java.util.List;import de.fitnesscoach.data.db.FitnessCoachDatabase;import de.fitnesscoach.data.entity.*;
public class RoomFitnessCoachRepository implements FitnessCoachRepository{private final FitnessCoachDatabase db;public RoomFitnessCoachRepository(FitnessCoachDatabase db){this.db=db;}public UserProfileEntity getProfile(){return db.profileDao().getProfile();}public void saveProfile(UserProfileEntity v){db.profileDao().upsertProfile(v);}public List<TrainingAvailabilityEntity>getAvailability(){return db.profileDao().getAvailability();}public void saveAvailability(TrainingAvailabilityEntity v){db.profileDao().upsertAvailability(v);}public GoalEntity getActiveGoal(){return db.goalDao().getActive();}public long insertGoal(GoalEntity v){return db.goalDao().insert(v);}public DailyHealthEntity getDailyHealth(LocalDate d){return db.healthDao().get(d);}public void saveDailyHealth(DailyHealthEntity v){db.healthDao().upsert(v);}public List<WorkoutEntity>getWorkouts(){return db.workoutDao().getWorkouts();}public long insertWorkout(WorkoutEntity v){return db.workoutDao().insertWorkout(v);}public void updateWorkout(WorkoutEntity v){db.workoutDao().updateWorkout(v);}public List<PlannedWorkoutEntity>getPlannedWorkouts(LocalDate f,LocalDate t){return db.workoutDao().plannedRange(f,t);}public long insertPlannedWorkout(PlannedWorkoutEntity v){return db.workoutDao().insertPlanned(v);}public void updatePlannedWorkout(PlannedWorkoutEntity v){db.workoutDao().updatePlanned(v);}public CheckInEntity getCheckIn(LocalDate d){return db.coachingDao().getCheckIn(d);}public void saveCheckIn(CheckInEntity v){db.coachingDao().upsertCheckIn(v);}public BaselineEntity getBaseline(String m,int w){return db.coachingDao().getBaseline(m,w);}public void saveBaseline(BaselineEntity v){db.coachingDao().upsertBaseline(v);}public RecoveryEntity getRecovery(LocalDate d){return db.coachingDao().getRecovery(d);}public void saveRecovery(RecoveryEntity v){db.coachingDao().upsertRecovery(v);}public List<CoachMemoryEntity>getActiveMemories(){return db.coachingDao().getActiveMemories();}public long insertMemory(CoachMemoryEntity v){return db.coachingDao().insertMemory(v);}public List<CoachDecisionEntity>getDecisions(){return db.coachingDao().getDecisions();}public long insertDecision(CoachDecisionEntity v){return db.coachingDao().insertDecision(v);}}
